"""Selected complete PIPL articles from the CAC publication (2021-08-20).

Source: https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm
Verified against that published text on 2026-09-11. Cross-border implementation
rules and exemptions still require case-specific verification; this is not a full corpus.
"""
from knowledge_base.models import normalize_record, KBType

SOURCE_URL = 'https://www.cac.gov.cn/2021-08/20/c_1631050028355286.htm'
ARTICLES = [
 (6, '第六条', '目的与最小必要', '处理个人信息应当具有明确、合理的目的，并应当与处理目的直接相关，采取对个人权益影响最小的方式。\n收集个人信息，应当限于实现处理目的的最小范围，不得过度收集个人信息。'),
 (13, '第十三条', '处理合法性基础', '符合下列情形之一的，个人信息处理者方可处理个人信息：\n（一）取得个人的同意；\n（二）为订立、履行个人作为一方当事人的合同所必需，或者按照依法制定的劳动规章制度和依法签订的集体合同实施人力资源管理所必需；\n（三）为履行法定职责或者法定义务所必需；\n（四）为应对突发公共卫生事件，或者紧急情况下为保护自然人的生命健康和财产安全所必需；\n（五）为公共利益实施新闻报道、舆论监督等行为，在合理的范围内处理个人信息；\n（六）依照本法规定在合理的范围内处理个人自行公开或者其他已经合法公开的个人信息；\n（七）法律、行政法规规定的其他情形。\n依照本法其他有关规定，处理个人信息应当取得个人同意，但是有前款第二项至第七项规定情形的，不需取得个人同意。'),
 (19, '第十九条', '保存期限', '除法律、行政法规另有规定外，个人信息的保存期限应当为实现处理目的所必要的最短时间。'),
 (21, '第二十一条', '委托处理与转委托', '个人信息处理者委托处理个人信息的，应当与受托人约定委托处理的目的、期限、处理方式、个人信息的种类、保护措施以及双方的权利和义务等，并对受托人的个人信息处理活动进行监督。\n受托人应当按照约定处理个人信息，不得超出约定的处理目的、处理方式等处理个人信息；委托合同不生效、无效、被撤销或者终止的，受托人应当将个人信息返还个人信息处理者或者予以删除，不得保留。\n未经个人信息处理者同意，受托人不得转委托他人处理个人信息。'),
 (25, '第二十五条', '公开个人信息', '个人信息处理者不得公开其处理的个人信息，取得个人单独同意的除外。'),
 (28, '第二十八条', '敏感个人信息', '敏感个人信息是一旦泄露或者非法使用，容易导致自然人的人格尊严受到侵害或者人身、财产安全受到危害的个人信息，包括生物识别、宗教信仰、特定身份、医疗健康、金融账户、行踪轨迹等信息，以及不满十四周岁未成年人的个人信息。\n只有在具有特定的目的和充分的必要性，并采取严格保护措施的情形下，个人信息处理者方可处理敏感个人信息。'),
 (29, '第二十九条', '敏感信息同意规则', '处理敏感个人信息应当取得个人的单独同意；法律、行政法规规定处理敏感个人信息应当取得书面同意的，从其规定。'),
 (38, '第三十八条', '跨境提供条件', '个人信息处理者因业务等需要，确需向中华人民共和国境外提供个人信息的，应当具备下列条件之一：\n（一）依照本法第四十条的规定通过国家网信部门组织的安全评估；\n（二）按照国家网信部门的规定经专业机构进行个人信息保护认证；\n（三）按照国家网信部门制定的标准合同与境外接收方订立合同，约定双方的权利和义务；\n（四）法律、行政法规或者国家网信部门规定的其他条件。\n中华人民共和国缔结或者参加的国际条约、协定对向中华人民共和国境外提供个人信息的条件等有规定的，可以按照其规定执行。\n个人信息处理者应当采取必要措施，保障境外接收方处理个人信息的活动达到本法规定的个人信息保护标准。'),
 (39, '第三十九条', '跨境告知与同意', '个人信息处理者向中华人民共和国境外提供个人信息的，应当向个人告知境外接收方的名称或者姓名、联系方式、处理目的、处理方式、个人信息的种类以及个人向境外接收方行使本法规定权利的方式和程序等事项，并取得个人的单独同意。'),
 (44, '第四十四条', '个人权利', '个人对其个人信息的处理享有知情权、决定权，有权限制或者拒绝他人对其个人信息进行处理；法律、行政法规另有规定的除外。'),
 (45, '第四十五条', '查阅复制与转移', '个人有权向个人信息处理者查阅、复制其个人信息；有本法第十八条第一款、第三十五条规定情形的除外。\n个人请求查阅、复制其个人信息的，个人信息处理者应当及时提供。\n个人请求将个人信息转移至其指定的个人信息处理者，符合国家网信部门规定条件的，个人信息处理者应当提供转移的途径。'),
 (46, '第四十六条', '更正补充', '个人发现其个人信息不准确或者不完整的，有权请求个人信息处理者更正、补充。\n个人请求更正、补充其个人信息的，个人信息处理者应当对其个人信息予以核实，并及时更正、补充。'),
 (47, '第四十七条', '删除与保存例外', '有下列情形之一的，个人信息处理者应当主动删除个人信息；个人信息处理者未删除的，个人有权请求删除：\n（一）处理目的已实现、无法实现或者为实现处理目的不再必要；\n（二）个人信息处理者停止提供产品或者服务，或者保存期限已届满；\n（三）个人撤回同意；\n（四）个人信息处理者违反法律、行政法规或者违反约定处理个人信息；\n（五）法律、行政法规规定的其他情形。\n法律、行政法规规定的保存期限未届满，或者删除个人信息从技术上难以实现的，个人信息处理者应当停止除存储和采取必要的安全保护措施之外的处理。'),
 (51, '第五十一条', '安全保护措施', '个人信息处理者应当根据个人信息的处理目的、处理方式、个人信息的种类以及对个人权益的影响、可能存在的安全风险等，采取下列措施确保个人信息处理活动符合法律、行政法规的规定，并防止未经授权的访问以及个人信息泄露、篡改、丢失：\n（一）制定内部管理制度和操作规程；\n（二）对个人信息实行分类管理；\n（三）采取相应的加密、去标识化等安全技术措施；\n（四）合理确定个人信息处理的操作权限，并定期对从业人员进行安全教育和培训；\n（五）制定并组织实施个人信息安全事件应急预案；\n（六）法律、行政法规规定的其他措施。'),
 (55, '第五十五条', '保护影响评估', '有下列情形之一的，个人信息处理者应当事前进行个人信息保护影响评估，并对处理情况进行记录：\n（一）处理敏感个人信息；\n（二）利用个人信息进行自动化决策；\n（三）委托处理个人信息、向其他个人信息处理者提供个人信息、公开个人信息；\n（四）向境外提供个人信息；\n（五）其他对个人权益有重大影响的个人信息处理活动。'),
 (57, '第五十七条', '泄露等事件补救与通知', '发生或者可能发生个人信息泄露、篡改、丢失的，个人信息处理者应当立即采取补救措施，并通知履行个人信息保护职责的部门和个人。通知应当包括下列事项：\n（一）发生或者可能发生个人信息泄露、篡改、丢失的信息种类、原因和可能造成的危害；\n（二）个人信息处理者采取的补救措施和个人可以采取的减轻危害的措施；\n（三）个人信息处理者的联系方式。\n个人信息处理者采取措施能够有效避免信息泄露、篡改、丢失造成危害的，个人信息处理者可以不通知个人；履行个人信息保护职责的部门认为可能造成危害的，有权要求个人信息处理者通知个人。'),
 (59, '第五十九条', '受托人的安全与协助义务', '接受委托处理个人信息的受托人，应当依照本法和有关法律、行政法规的规定，采取必要措施保障所处理的个人信息的安全，并协助个人信息处理者履行本法规定的义务。'),
]


def get_records():
    return [normalize_record({'id':f'pipl_{num}', 'title':f'个人信息保护法{article} {name}',
        'content':text, 'citation':f'《中华人民共和国个人信息保护法》{article}',
        'source':'中华人民共和国个人信息保护法', 'article_or_clause':article,
        'source_url':SOURCE_URL, 'effective_from':'2021-11-01', 'document_version':'2021',
        'document_id':'pipl_2021', 'authority_level':'statute', 'category':'个人信息保护',
        'tags':['个人信息',name], 'status':'published','review_status':'published',
        'verified_at':'2026-09-11'}, KBType.LEGAL.value) for num,article,name,text in ARTICLES]
